31	/**
32	 * tiling kernel的context
33	 */
34	class TilingContext : public ExtendedKernelContext {
35	 public:
36	  const void *GetCompileInfo() const {
37	    const auto compute_node_info = GetComputeNodeInfo();
38	    if (compute_node_info == nullptr) {
39	      return nullptr;
40	    }
41	
42	    const size_t index = compute_node_info->GetInputsNum() + compute_node_info->GetOutputsNum();
43	    const auto av = GetInput(index);
44	    if (av == nullptr) {
45	      return nullptr;
46	    }
47	    return av->GetValue<void *>();
48	  }
49	  /**
50	   * 获取CompileInfo
51	   * @tparam T CompileInfo的类型
52	   * @return CompileInfo的指针
53	   */
54	  template <typename T>
55	  const T *GetCompileInfo() const {
56	    return reinterpret_cast<const T *>(GetCompileInfo());
57	  }
58	  /**
59	   * 获取输入shape，输入shape中包含了原始shape与运行时shape
60	   * @param index 输入index
61	   * @return 输入shape指针，index非法时返回空指针
62	   */
63	  const StorageShape *GetInputShape(const size_t index) const {
64	    const auto compute_node_info = GetComputeNodeInfo();
65	    if (compute_node_info == nullptr) {
66	      return nullptr;
67	    }
68	
69	    if (index >= compute_node_info->GetInputsNum()) {
70	      return nullptr;
71	    }
72	    return GetInputPointer<StorageShape>(index);
73	  }
74	  /**
75	   * 获取输入tensor
76	   * 若算子被配置为'tiling'数据依赖，则返回的Tensor对象中保存了Host内存地址；反之，内存地址为nullptr。
77	   * @param index 输入index
78	   * @return 输入tensor指针，index非法时返回空指针
79	   */
80	  const Tensor *GetInputTensor(const size_t index) const {
81	    return GetInputPointer<Tensor>(index);
82	  }
83	  /**
84	   * 基于算子IR原型定义，获取`OPTIONAL_INPUT`类型的输入tensor指针
85	   * 若算子被配置为'tiling'数据依赖，则返回的Tensor对象中保存了Host内存地址；反之，内存地址为nullptr。
86	   * @param ir_index IR原型定义中的index
87	   * @return tensor指针，index非法，或该INPUT没有实例化时，返回空指针
88	   */
89	  const Tensor *GetOptionalInputTensor(const size_t ir_index) const {
90	    return GetDynamicInputPointer<Tensor>(ir_index, 0);
91	  }
92	  /**
93	   * 基于算子IR原型定义，获取`DYNAMIC_INPUT`类型的输入Tensor指针
94	   * 若算子被配置为'tiling'数据依赖，则返回的Tensor对象中保存了Host内存地址；反之，内存地址为nullptr。
95	   * @param ir_index IR原型定义中的index
96	   * @param relative_index
97	   * 该输入实例化后的相对index，例如某个DYNAMIC_INPUT实例化了3个输入，那么relative_index的有效范围是[0,2]
98	   * @return Tensor指针，index或relative_index非法时，返回空指针
99	   */
100	  const Tensor *GetDynamicInputTensor(const size_t ir_index, const size_t relative_index) const {
101	    return GetDynamicInputPointer<Tensor>(ir_index, relative_index);
102	  }
103	  /**
104	   * 基于算子IR原型定义，获取`OPTIONAL_INPUT`类型的输入shape指针，shape中包含了原始shape与运行时shape
105	   * @param ir_index IR原型定义中的index
106	   * @return shape指针，index非法，或该INPUT没有实例化时，返回空指针
107	   */
108	  const StorageShape *GetOptionalInputShape(const size_t ir_index) const {
109	    return GetDynamicInputPointer<StorageShape>(ir_index, 0);
110	  }
111	  /**
112	   * 基于算子IR原型定义，获取`REQUIRED_INPUT`类型的输入Tensor指针
113	   * 若算子被配置为'tiling'数据依赖，则返回的Tensor对象中保存了Host内存地址；反之，内存地址为nullptr。
114	   * @param ir_index IR原型定义中的index
115	   * @return Tensor指针，index非法时，返回空指针
116	   */
117	  const Tensor *GetRequiredInputTensor(const size_t ir_index) const {
118	    return GetDynamicInputPointer<Tensor>(ir_index, 0);
119	  }
120	  /**
121	   * 基于算子IR原型定义，获取`REQUIRED_INPUT`类型的输入shape指针，shape中包含了原始shape与运行时shape
122	   * @param ir_index IR原型定义中的index
123	   * @return shape指针，index非法，或该INPUT没有实例化时，返回空指针
124	   */
125	  const StorageShape *GetRequiredInputShape(const size_t ir_index) const {
126	    return GetDynamicInputPointer<StorageShape>(ir_index, 0);
127	  }
128	  /**
129	   * 基于算子IR原型定义，获取`DYNAMIC_INPUT`类型的输入shape指针，shape中包含了原始shape与运行时shape
130	   * @param ir_index IR原型定义中的index
131	   * @param relative_index
132	   * 该输入实例化后的相对index，例如某个DYNAMIC_INPUT实例化了3个输入，那么relative_index的有效范围是[0,2]
133	   * @return shape指针，index或relative_index非法时，返回空指针
134	   */
135	  const StorageShape *GetDynamicInputShape(const size_t ir_index, const size_t relative_index) const {
136	    return GetDynamicInputPointer<StorageShape>(ir_index, relative_index);
137	  }
138	  /**
139	   * 根据输出index，获取输出shape指针，shape中包含了原始shape与运行时shape
140	   * @param index 输出index
141	   * @return 输出shape指针，index非法时，返回空指针
142	   */
143	  const StorageShape *GetOutputShape(const size_t index) const {
144	    const auto compute_node_info = GetComputeNodeInfo();
145	    if (compute_node_info == nullptr) {
146	      return nullptr;
147	    }
148	
149	    if (index >= compute_node_info->GetOutputsNum()) {
150	      return nullptr;
151	    }
152	
153	    const size_t offset = compute_node_info->GetInputsNum();
154	    return GetInputPointer<StorageShape>(offset + index);
155	  }
