157	  /*
158	   * outputs, tiling的outputs以如下顺序排列：
159	   * outputs[0]: tiling-key
160	   * outputs[1]: block-dim
161	   * outputs[2]: atomic-clean-flag
162	   * outputs[3]: tiling-data
163	   * outputs[4]: workspace sizes
164	   * outputs[5]: tiling condition
165	   * outputs[6]: schedule mode
166	   * outputs[7]: local memory size
167	   * outputs[8]: aicpu block-dim
168	   */
169	  enum TilingOutputIndex : uint32_t {
170	    kOutputTilingKey = 0,
171	    kOutputBlockDim = 1,  // 接口即将废弃；优先选择 kOutputSimdNumBlocks
172	    kOutputSimdNumBlocks = 1,
173	    kOutputAtomicCleanFlag = 2,
174	    kOutputTilingData = 3,
175	    kOutputWorkspace = 4,
176	    kOutputTilingCond = 5,
177	    kOutputScheduleMode = 6,
178	    kOutputLocalMemorySize = 7,  // 接口即将废弃；优先选择 kOutputDynUBufSize
179	    kOutputDynUBufSize = 7,
180	    kOutputAicpuBlockDim = 8,  // 接口即将废弃；优先选择 kOutputAicpuNumBlocks
181	    kOutputAicpuNumBlocks = 8,
182	    kOutputSimtBlockDim = 9,
183	    kOutputSimtGridDim = 10,
184	    // add new output definitions here
185	    kOutputNum
186	  };
187	
188	  /*
189	   * outputs[0]: fallible tiling condition
190	   */
191	  enum FallibleTilingOutputIndex : uint32_t {
192	    kTilingStatus = TilingOutputIndex::kOutputNum,
193	    // add new output definitions here
194	    kFallibleOutputNum
195	  };
