389	  /**
390	   * 获取有类型的tiling data指针
391	   * @tparam T tiling data类型，sizeof(T)不可以大于编译结果中指定的最大tiling data长度
392	   * @return tiling data指针，失败时返回空指针
393	   */
394	  template <typename T>
395	  auto GetTilingData() -> T * {
396	    auto tiling_data = GetRawTilingData();
397	    if (tiling_data == nullptr) {
398	      return nullptr;
399	    }
400	    if (tiling_data->GetCapacity() < sizeof(T)) {
401	      return nullptr;
402	    }
403	    tiling_data->SetDataSize(sizeof(T));
404	    return static_cast<T *>(tiling_data->GetData());
405	  }
