416	   * @return workspace sizes指针
417	   */
418	  size_t *GetWorkspaceSizes(const size_t workspace_count) {
419	    const auto workspace = GetOutputPointer<TypedContinuousVector<size_t>>(kOutputWorkspace);
420	    if (workspace == nullptr) {
421	      return nullptr;
422	    }
423	    if (workspace->SetSize(workspace_count) != ge::SUCCESS) {
424	      return nullptr;
425	    }
426	    return workspace->MutableData();
427	  }
